#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.15.0  -  Comments rebuilt, real stickers, clip timeline, cleaner buttons
#   * Epidemic Sound 400: the signer retries plainly and shows Epidemic's own reason.
#   * Editor: tap a text or sticker to select it; size slider, +/- buttons, corner handle,
#     pinch; Edit and Delete on the selected item.
#   * Real stickers (Giphy) with an Emoji tab; photos get a still frame baked in.
#   * Clip editor: a timeline with frames, handles that snap to seconds, playhead, scrub.
#   * Smaller like / comment / share / repost / save buttons everywhere.
#   * Repost in Discover. Clips: no More button, Follow next to the username, Report under Share.
#   * Comments: likes, replies, GIF / photo / clip answers, long-press menu, edited mark.
#   * Clips title and back button hide while you scroll down, return when you scroll up.
#   * A short buzz on any press-and-hold.
# Run from the project root:   bash update_v1150_comments_stickers_timeline.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="138ce8783c50e35367e334b238c9c0f44c787c4f10f548f19334782b5e6afd0e"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/screens/post/editor_screen.dart ] || { echo "ERROR: v1.14.0 is not installed. Run update_v1140_editor_reposts_languages.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.15.0 is in place."
echo ""
echo "IMPORTANT (once):"
echo "  1) Firestore rules: Firebase console -> Firestore Database -> Rules, paste the full"
echo "     contents of firebase/firestore.rules and press Publish. Comment likes, replies"
echo "     and edits need them."
echo "  2) Audio search (Epidemic): commit and push, then Vercel -> signer project ->"
echo "     Deployments -> Redeploy. This update changes the signer; without the redeploy"
echo "     the old signer keeps running."
echo "  3) Stickers need your Giphy key (the same one that makes GIFs work in chat)."
exit 0
